#include<bits/stdc++.h>
using namespace std;

bool a[100000001]; // As 10^4*10^4 = 100000000 >> max limit for the Histogram // extra 1 is for 0 base indexing

int main(){

int n, result = 0;
cin>> n;
long int range = 10000*10000;

for(int i=1; i<=n; i++){long int x = i*i; a[x]=true;}

for(int i=1; i<=n; i++)
    for(int j=i+1; j<=n; j++){
      long int x = i*i+j*j;
      if(range >= x)(a[x])? result++ : result +=0; // to get rid of out of bound error
}

cout << result;

return 0;
}
